/* Toybox Town service worker. Generated by scripts/build-pwa.js; don't edit dist/sw.js. */
const VERSION = __VERSION__;
const BASE = __BASE__;
const PRECACHE = __PRECACHE__;
const CACHE = `toybox-${VERSION}`;
const RUNTIME = 'toybox-runtime';
const INDEX = `${BASE}/index.html`;

self.addEventListener('install', (event) => {
  // `cache: 'reload'` skips the browser cache so a new version gets fresh files.
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' }))),
    ),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((k) => k.startsWith('toybox-') && k !== CACHE && k !== RUNTIME).map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

// The app can ask a waiting update to take over (used by a future "update ready" prompt).
self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

function inScope(url) {
  return url.origin === self.location.origin && url.pathname.startsWith(`${BASE}/`);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  // Leave everything else alone, including Home Assistant's own /api and /auth.
  if (!inScope(url)) return;

  if (request.mode === 'navigate') {
    // Pages: try the network briefly so updates show up, else the saved app.
    event.respondWith(
      Promise.race([
        fetch(request).then((res) => (res.ok ? res : Promise.reject(res))),
        new Promise((_, reject) => setTimeout(reject, 3000)),
      ]).catch(() => caches.match(INDEX).then((res) => res || Response.error())),
    );
    return;
  }

  // Files: saved copy first (they're versioned), else fetch and keep a copy.
  event.respondWith(
    caches.match(request).then(
      (cached) =>
        cached ||
        fetch(request).then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(RUNTIME).then((cache) => cache.put(request, copy));
          }
          return res;
        }),
    ),
  );
});
